export function createQueue(options = {}) {
  const { onEvent } = options;
  const items = [];
  return {
    push(item) {
      items.push(item);
      onEvent?.({ type: 'push', item });
    },
    shift() {
      if (items.length === 0) return undefined;
      const item = items.shift();
      onEvent?.({ type: 'shift', item });
      return item;
    },
    size: () => items.length,
  };
}

export function createWorker(handler, options = {}) {
  const { onEvent } = options;
  return {
    async run(queue) {
      let done = 0;
      while (queue.size() > 0) {
        const item = queue.shift();
        try {
          await handler(item);
          done += 1;
          onEvent?.({ type: 'done', item });
        } catch (error) {
          onEvent?.({ type: 'error', item, error });
        }
      }
      return done;
    },
  };
}

import { createQueue } from './queue.js';
import { createWorker } from './worker.js';

export { createQueue, createWorker };

export function createSystem(handler, options = {}) {
  return {
    queue: createQueue(options),
    worker: createWorker(handler, options),
  };
}
